def solve(candidates, target):
    candidates=sorted(candidates); result=[]
    def visit(start,remaining,path):
        if remaining==0: result.append(path.copy()); return
        for i in range(start,len(candidates)):
            value=candidates[i]
            if value>remaining: break
            path.append(value); visit(i,remaining-value,path); path.pop()
    visit(0,target,[])
    return result
